const K=()=>localStorage.getItem('studio.gkey')||'',MD=()=>localStorage.getItem('studio.gmodel')||'gemini-flash-latest';
async function gem(parts,o={}){const k=K();if(!k)throw new Error('Manca la chiave API Gemini (⋮ → Assistente AI).');
 for(let t=0;t<3;t++){const r=await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${MD()}:generateContent`,{method:'POST',headers:{'Content-Type':'application/json','x-goog-api-key':k},body:JSON.stringify({contents:o.contents||[{role:'user',parts}],...(o.sys?{systemInstruction:{parts:[{text:o.sys}]}}:{}),...(o.json?{generationConfig:{responseMimeType:'application/json'}}:{})})});
  if(r.status==429&&t<2){await new Promise(a=>setTimeout(a,12000));continue}
  const j=await r.json();if(!r.ok)throw new Error(j.error?.message||'Errore '+r.status);return(j.candidates?.[0]?.content?.parts||[]).map(p=>p.text||'').join('')}
 throw new Error('Limite di richieste raggiunto: riprova tra un minuto.')}
const ctx=d=>'Sei un tutor di studio per uno studente universitario di dietistica. Rispondi sempre in italiano, in modo chiaro e conciso, basandoti sul documento seguente; se la risposta non è nel documento, dillo. DOCUMENTO:\n'+sents(d).map(s=>s.t).join('').slice(0,150000);
const aiFmt=t=>esc(t).replace(/\*\*(.+?)\*\*/g,'<b>$1</b>').replace(/\n/g,'<br>');
async function aiRun(prompt,show,json){const d=doc();d.chat=d.chat||[];const h=d.chat.filter(m=>!m.err).slice(-12).map(m=>({role:m.r=='u'?'user':'model',parts:[{text:m.t}]}));d.chat.push({r:'u',t:show});S.ai=1;S.panel='ai';render();let t=null;
 try{h.push({role:'user',parts:[{text:prompt}]});t=await gem(null,{sys:ctx(d),contents:h,json})}catch(e){d.chat.push({r:'m',t:'⚠ '+e.message,err:1})}S.ai=0;return t}
const aiDone=(d,t)=>{if(t)d.chat.push({r:'m',t});if(d.chat.length>40)d.chat=d.chat.slice(-40);save();render()};
async function aiSend(){const q=$('#ai1').value.trim();if(!q)return;const d=doc();aiDone(d,await aiRun(q,q))}
async function aiQuick(k){const d=doc(),L=sents(d),c=L[Math.min(S.i,L.length-1)],par=L.filter(x=>x.pi==c.pi).map(x=>x.t).join('').trim();
 if(k=='expl')return aiDone(d,await aiRun(`Spiega in modo semplice questa frase del documento: "${c.t.trim()}"`,'Spiega la frase'));
 if(k=='sum'){const t=await aiRun(`Riassumi in 3-4 frasi questo paragrafo: "${par}"`,'Riassumi il paragrafo');if(t){d.s.push({id:Date.now(),x:t.trim()});return aiDone(d,'Riassunto salvato nel pannello Riassunti:\n\n'+t)}return aiDone(d,null)}
 const t=await aiRun(`Crea da 3 a 5 flashcard (domanda e risposta brevi) su questo paragrafo: "${par}". Rispondi solo con JSON: [{"q":"...","a":"..."}]`,'Crea flashcard',true);
 if(t)try{const a=JSON.parse(t.replace(/^```json|```$/g,'').trim());a.forEach((x,i)=>d.q.push({id:Date.now()+i,q:String(x.q),a:String(x.a),box:1,due:today()}));return aiDone(d,`Ho creato ${a.length} flashcard: le trovi nel pannello Domande.`)}catch(e){return aiDone(d,'⚠ Risposta non valida, riprova.')}aiDone(d,null)}
function aiPanel(d){d.chat=d.chat||[];const tabs=`<div class=seg style="margin-bottom:8px"><button onclick="A('panel','kw')">Contenuti</button><button class=on>Tutor AI</button></div>`;
 if(!K())return`<div class=side>${tabs}<h3>Tutor AI</h3><div class=empty style="padding:24px 6px"><div class=ic>${I('sparkles')}</div><div class=mut>Il tutor risponde alle domande sul testo, riassume e crea flashcard. Serve una chiave API gratuita di Gemini.</div><p><button class=pri onclick="A('modal','key')">Aggiungi la chiave</button></p></div></div>`;
 return`<div class=side>${tabs}<h3>Tutor AI</h3><div style="display:flex;gap:6px;flex-wrap:wrap;margin:6px 0"><button onclick="aiQuick('expl')">Spiega la frase</button><button onclick="aiQuick('sum')">Riassumi paragrafo</button><button onclick="aiQuick('qs')">Crea flashcard</button></div><div class=chat>${d.chat.map(m=>`<div class="msg ${m.r}">${aiFmt(m.t)}</div>`).join('')}${S.ai?'<div class="msg m mut">Sto pensando…</div>':''}</div><textarea id=ai1 rows=2 placeholder="Chiedi qualcosa sul testo…"></textarea><div style="display:flex;gap:6px"><button class=pri style="flex:1" onclick="aiSend()">${I('send')}Invia</button><button onclick="doc().chat=[];save();render()">${I('trash-2')}</button></div></div>`}
function modalAI(){if(S.modal!='key')return'';return`<div class=ov onclick="A('close')"></div><div class=modal><h2>Assistente AI (Gemini)</h2><div class=mut>1. Apri aistudio.google.com/apikey e accedi con il tuo account Google.<br>2. Tocca “Crea chiave API” e copiala.<br>3. Incollala qui sotto.</div><div class=lab style="margin-top:12px">Chiave API</div><input id=gk type=password value="${esc(K())}" placeholder="AIza…"><div class=lab>Modello</div><input id=gm value="${esc(MD())}"><p class=mut>La chiave resta solo su questo dispositivo e non viene sincronizzata. Con il piano gratuito Google può usare i contenuti inviati per migliorare i suoi prodotti: non inviare dati sensibili.</p><button onclick="A('close')">Annulla</button> <button onclick="aiKey();aiTest()">Prova</button> <button class=pri onclick="aiKey();S.modal=null;render()">Salva</button></div>`}
const aiKey=()=>{localStorage.setItem('studio.gkey',$('#gk').value.trim());localStorage.setItem('studio.gmodel',$('#gm').value.trim()||'gemini-flash-latest')};
async function aiTest(){try{tell('Funziona: '+await gem([{text:'Rispondi solo con la parola ok'}]))}catch(e){tell('Errore: '+e.message)}}
async function ocrPdf(buf){if(!K())throw new Error('Per leggere i PDF scansionati serve la chiave Gemini: ⋮ → Assistente AI.');const lib=await pj(),pdf=await lib.getDocument({data:new Uint8Array(buf.slice(0))}).promise,out=[],N=Math.min(pdf.numPages,40);
 for(let n=1;n<=N;n++){S.msg=`Riconoscimento del testo: pagina ${n} di ${N}…`;render();const pg=await pdf.getPage(n),vp=pg.getViewport({scale:1.6}),c=document.createElement('canvas');c.width=vp.width;c.height=vp.height;await pg.render({canvasContext:c.getContext('2d'),viewport:vp}).promise;
  const t=await gem([{inlineData:{mimeType:'image/jpeg',data:c.toDataURL('image/jpeg',.75).split(',')[1]}},{text:'Trascrivi fedelmente tutto il testo di questa pagina, senza commenti. Separa i paragrafi con una riga vuota. Ignora numeri di pagina e intestazioni ripetute.'}]);out.push(...t.split(/\n\s*\n/).map(s=>s.replace(/\s+/g,' ').trim()).filter(Boolean))}S.msg=null;return out}
/* ---- indice, anteprime, esportazione mappe ---- */
const sideMenu=()=>mn('top:56px;left:60px',`<div class=h>BARRA LATERALE</div>${tip('Indice',"A('side','idx')")}${doc().kind=='pdf'?tip('Anteprime pagine',"A('side','th')"):''}`);
const mexpMenu=()=>mn('top:110px;left:50%;transform:translateX(-50%)',`<div class=h>ESPORTA MAPPA</div>${tip('Immagine PNG',"mapExp('png')")}${tip('Immagine SVG',"mapExp('svg')")}${tip('Stampa',"mapExp('print')")}`);
function jumpTo(i){S.i=i;PV.sc=1;if(innerWidth<700)S.side=null;save();render()}
function jumpPage(n){const L=sents(doc()),k=L.findIndex(s=>s.pg==n);if(innerWidth<700)S.side=null;if(k>=0)jumpTo(k);else{render();PV.el&&PV.el.scrollTo({top:PV.shells[n].offsetTop-8,behavior:'smooth'})}}
async function fillThumbs(){if(S.side!='th'||PV.id!=S.cur||!PV.pdf)return;PV.th=PV.th||{};for(const im of document.querySelectorAll('img[data-th]')){const n=+im.dataset.th;if(!PV.th[n]){const pg=await PV.pdf.getPage(n+1),vp=pg.getViewport({scale:.25}),c=document.createElement('canvas');c.width=vp.width;c.height=vp.height;await pg.render({canvasContext:c.getContext('2d'),viewport:vp}).promise;PV.th[n]=c.toDataURL('image/jpeg',.7)}im.src=PV.th[n]}}

async function aiMeta(r){try{const t=(r.model?r.model.pages[0].text:r.paras.slice(0,12).join('\n')).slice(0,3500);const j=JSON.parse((await gem([{text:'Dal testo della prima pagina di un documento accademico estrai i metadati. Rispondi solo con JSON: {"titolo":"","autori":["Cognome N."],"anno":"AAAA"}. Usa stringa vuota o lista vuota se un dato non è presente.\n\n'+t}],{json:true})).replace(/^```json|```$/g,'').trim());if(j.titolo)r.title=String(j.titolo);if(Array.isArray(j.autori)&&j.autori.length)r.authors=j.autori.map(String);if(j.anno)r.year=String(j.anno)}catch(e){}}
